      "attribute": "legal.verdict",
      "status": "found",
      "raw_value": "The Court is disposed to grant an interlocutory injunction, not in mandatory terms requiring the first respondent to change the colour scheme on the front of the store but rather restraining it from trading at that store until such time as it changes the colour scheme on the front of the store to a colour scheme which arguably does not misrepresent or pass off itself in relation to the Clark Rubber colour scheme.",
      "normalized_value": "Guilty",
      "unit": null,
      "period": null,
      "evidence": [
        {
          "source_id": "452.txt",
          "exact_span": "In all these circumstances, subject to the applicants offering the usual undertaking as to damages, I am disposed to grant an interlocutory injunction, not in mandatory terms requiring the first respondent to change the colour scheme on the front of the store but rather restraining it from trading at that store until such time as it changes the colour scheme on the front of the store to a colour scheme which arguably does not misrepresent or pass off itself in relation to the Clark Rubber colour scheme."
        }
      ]
